def extract_3x3_from_8s(grid):
    """Find the 3x3 region containing all 8s"""
    all_rows = []
    all_cols = []
    for r in range(9):
        for c in range(9):
            if grid[r][c] == 8:
                all_rows.append(r)
                all_cols.append(c)

    if not all_rows:
        return None

    found_box = None
    for start_r in range(7):  # 0 to 6
        for start_c in range(7):  # 0 to 6
            for r in all_rows:
                for c in all_cols:
                    if not (start_r <= r <= start_r+2 and start_c <= c <= start_c+2):
                        break  # This start position doesn't include all 8s
                else:
                    continue
                break  # Found one 8 outside
